# Generated by unmv. Sources only an unmv helper; mv is unchanged.
function global:unmv {
    $unmvType = 'unknown'
    $unmvCommand = ''
    $unmvDescription = ''
    $unmvResolved = Microsoft.PowerShell.Core\Get-Command -Name mv -All -ListImported -ErrorAction SilentlyContinue | Select-Object -First 1
    for ($unmvDepth = 0; $unmvDepth -lt 16 -and $null -ne $unmvResolved; $unmvDepth++) {
        if ($unmvResolved.CommandType -eq 'Alias') {
            $unmvDescription += "$($unmvResolved.Name)=$($unmvResolved.Definition); "
            $unmvResolved = Microsoft.PowerShell.Core\Get-Command -Name $unmvResolved.Definition -All -ListImported -ErrorAction SilentlyContinue | Select-Object -First 1
        } else { break }
    }
    if ($null -ne $unmvResolved) {
        if ($unmvResolved.CommandType -eq 'Cmdlet' -and $unmvResolved.Name -eq 'Move-Item' -and $unmvResolved.ModuleName -eq 'Microsoft.PowerShell.Management') {
            $unmvType = 'powershell'
            $unmvCommand = 'Microsoft.PowerShell.Management\Move-Item'
        } elseif ($unmvResolved.CommandType -eq 'Application') {
            $unmvType = 'external'
            $unmvCommand = $unmvResolved.Source
        }
        $unmvDescription += "$($unmvResolved.CommandType): $($unmvResolved.Definition)"
    }
    if ($PWD.Provider.Name -ne 'FileSystem') {
        [Console]::Error.WriteLine('unmv: shell helper requires a FileSystem working location')
        $global:LASTEXITCODE = 1
        return
    }
    $unmvPowerShellOperands = $unmvType -eq 'powershell'
    # An explicit profile also defines array/provider handling for an unknown
    # wrapper. Keep the inspected command's identity in the child environment.
    for ($unmvIndex = 0; $unmvIndex -lt $args.Count; $unmvIndex++) {
        if ($args[$unmvIndex] -is [Array]) { continue }
        $unmvValue = [string]$args[$unmvIndex]
        if ($unmvValue -eq '--') { break }
        if ($unmvValue -eq '--mv-kind' -and $unmvIndex + 1 -lt $args.Count) {
            $unmvIndex++
            $unmvPowerShellOperands = [string]$args[$unmvIndex] -eq 'powershell'
        } elseif ($unmvValue.StartsWith('--mv-kind=')) {
            $unmvPowerShellOperands = $unmvValue.Substring(10) -eq 'powershell'
        }
    }
    $unmvArguments = New-Object 'System.Collections.Generic.List[string]'
    foreach ($unmvArgument in $args) {
        if ($unmvArgument -is [Array]) {
            if (-not $unmvPowerShellOperands) {
                [Console]::Error.WriteLine('unmv: array arguments are ambiguous for native mv; quote literal comma-containing paths')
                $global:LASTEXITCODE = 1
                return
            }
            foreach ($unmvSource in $unmvArgument) { $unmvArguments.Add([string]$unmvSource) }
        } else { $unmvArguments.Add([string]$unmvArgument) }
    }
    if ($unmvPowerShellOperands) {
        $unmvLiteral = $false
        $unmvSkipValue = $false
        for ($unmvIndex = 0; $unmvIndex -lt $unmvArguments.Count; $unmvIndex++) {
            $unmvValue = $unmvArguments[$unmvIndex]
            if ($unmvSkipValue) { $unmvSkipValue = $false; continue }
            if (-not $unmvLiteral -and $unmvValue -eq '--') { $unmvLiteral = $true; continue }
            if (-not $unmvLiteral -and $unmvValue -match '^--(?:mode|mv-kind|shell-integration|default-prompt-answer)$') { $unmvSkipValue = $true; continue }
            if (-not $unmvLiteral -and $unmvValue.StartsWith('-')) { continue }
            $unmvProvider = $null
            $unmvDrive = $null
            try {
                $unmvPath = $ExecutionContext.SessionState.Path.GetUnresolvedProviderPathFromPSPath($unmvValue, [ref]$unmvProvider, [ref]$unmvDrive)
                if ($unmvProvider.Name -ne 'FileSystem') { throw 'non-filesystem provider' }
                $unmvArguments[$unmvIndex] = $unmvPath
            } catch {
                [Console]::Error.WriteLine("unmv: cannot resolve filesystem path: $unmvValue")
                $global:LASTEXITCODE = 1
                return
            }
        }
    }
    $unmvStart = New-Object System.Diagnostics.ProcessStartInfo
    $unmvStart.FileName = @UNMV_BIN@
    $unmvStart.UseShellExecute = $false
    $unmvStart.WorkingDirectory = $PWD.ProviderPath
    $unmvStart.EnvironmentVariables['UNMV_CONTEXT_SHELL'] = 'pwsh'
    $unmvStart.EnvironmentVariables['UNMV_CONTEXT_TYPE'] = $unmvType
    $unmvStart.EnvironmentVariables['UNMV_CONTEXT_COMMAND'] = $unmvCommand
    $unmvStart.EnvironmentVariables['UNMV_CONTEXT_DESCRIPTION'] = $unmvDescription
    $unmvStart.EnvironmentVariables['UNMV_DEFAULT_PROMPT_ANSWER'] = '@UNMV_DEFAULT_PROMPT_ANSWER@'
    if ($null -ne $unmvStart.PSObject.Properties['ArgumentList']) {
        foreach ($unmvArgument in $unmvArguments) { $unmvStart.ArgumentList.Add($unmvArgument) }
    } else {
        # Windows PowerShell 5.1: quote using the Windows argv convention.
        $unmvQuoted = foreach ($unmvArgument in $unmvArguments) {
            '"' + ([regex]::Replace(([regex]::Replace($unmvArgument, '(\\*)"', '$1$1\"')), '(\\+)$', '$1$1')) + '"'
        }
        $unmvStart.Arguments = $unmvQuoted -join ' '
    }
    try {
        $unmvProcess = [System.Diagnostics.Process]::Start($unmvStart)
        $unmvProcess.WaitForExit()
        $global:LASTEXITCODE = $unmvProcess.ExitCode
        $unmvProcess.Dispose()
    } catch {
        [Console]::Error.WriteLine("unmv: could not launch executable: $_")
        $global:LASTEXITCODE = 1
    }
}
